const delay=ms=>new Promise(r=>setTimeout(r,ms));
const mean=s=>s[0].map((_,i)=>s.reduce((n,x)=>n+x[i],0)/s.length);
const distance=(a,b)=>Math.sqrt(a.reduce((s,x,i)=>s+(x-b[i])**2,0));
export class CameraTracker{
constructor(){this.live=false;this.screen=null;this.work=null;this.samples=null;this.lastVideo=-1;}
async start(video,callback){if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera needs HTTPS or localhost.');this.video=video;this.callback=callback;this.live=true;const request=navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:false});request.then(stream=>{if(!this.live)stream.getTracks().forEach(t=>t.stop());},()=>{});let timeout;try{this.stream=await Promise.race([request,new Promise((_,reject)=>{timeout=setTimeout(()=>reject(Error('Camera permission is still pending. Open in Safari or Chrome, allow camera access, then retry.')),15000);})]);}finally{clearTimeout(timeout);}if(!this.live){this.stream.getTracks().forEach(t=>t.stop());return;}video.srcObject=this.stream;await video.play();const{FaceLandmarker,FilesetResolver}=await import('./vendor/vision_bundle.mjs');if(!this.live)return;const vision=await FilesetResolver.forVisionTasks('./vendor');const detector=await FaceLandmarker.createFromOptions(vision,{baseOptions:{modelAssetPath:'./vendor/face_landmarker.task',delegate:'CPU'},runningMode:'VIDEO',numFaces:1,minFaceDetectionConfidence:.65,minFacePresenceConfidence:.65,minTrackingConfidence:.65});if(!this.live){detector.close();return;}this.detector=detector;this.interval=setInterval(()=>this.sample(),150);this.stream.getVideoTracks()[0].addEventListener('ended',()=>{this.failed=true;callback({looking:null,state:'stopped'});});}
features(l){const a=l[33],b=l[263],n=l[1],w=Math.hypot(a.x-b.x,a.y-b.y);if(w<.1||w>.7||n.x<.12||n.x>.88||n.y<.1||n.y>.9)return null;const iris=(i,left,right)=>[(l[i].x-l[left].x)/Math.max(.001,l[right].x-l[left].x),(l[i].y-(l[left].y+l[right].y)/2)/w],one=iris(468,33,133),two=iris(473,362,263);return[(n.x-(a.x+b.x)/2)/w,(n.y-(a.y+b.y)/2)/w,one[0]*.4,two[0]*.4,one[1]*2,two[1]*2];}
sample(){if(!this.live||!this.detector||this.video.readyState<2||document.hidden)return;if(this.failed){this.callback({looking:null,state:'stopped'});return;}if(this.video.currentTime===this.lastVideo){this.callback({looking:null,state:'unknown'});return;}this.lastVideo=this.video.currentTime;try{const result=this.detector.detectForVideo(this.video,performance.now()),l=result.faceLandmarks[0],f=l?.length>=478?this.features(l):null;if(f&&this.samples)this.samples.push(f);if(!f){this.callback({looking:null,state:l?'unknown':'missing'});return;}if(!this.screen||!this.work){this.callback({looking:null,state:'unknown'});return;}const a=distance(f,this.screen),b=distance(f,this.work),gap=distance(this.screen,this.work);this.callback({looking:a<gap*.9&&a+.015<b,state:'tracking'});}catch{this.callback({looking:null,state:'unknown'});}}
async capture(kind){this.samples=[];await delay(3200);const s=this.samples;this.samples=null;if(!this.live||!s)throw Error('Camera stopped. Close and retry.');if(s.length<12)throw Error('Your face was not clear enough. Improve lighting, move into the oval and retry.');const center=mean(s);if(s.reduce((n,x)=>n+distance(x,center),0)/s.length>.1)throw Error('Too much movement. Hold that position and retry.');this[kind]=center;}
verify(){if(!this.screen||!this.work||distance(this.screen,this.work)<.12){this.work=null;throw Error('Those positions look too similar. Move your work farther to the side or below the screen and retry.');}}
stop(){this.live=false;clearInterval(this.interval);this.stream?.getTracks().forEach(t=>t.stop());if(this.video)this.video.srcObject=null;this.detector?.close();this.detector=null;this.screen=null;this.work=null;this.samples=null;}
}
